sys_script_include.script:
var VenueUtils = Class.create();
VenueUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    checkVenueAvailabilityByName: function() {
        var venueName = this.getParameter('venueName');
        var result = {
            exists: false,
            msg: ''
        };

        if (!venueName) {
            result.msg = 'Venue name is required.';
            return JSON.stringify(result);
        }

        var gr = new GlideRecord('x_your_scope_venue_table'); // Replace with your actual Venue table name
        gr.addQuery('name', venueName); // Adjust 'name' to the actual field name used for venue name
        gr.query();

        if (gr.next()) {
            result.exists = true;
            result.msg = 'This venue is already booked. Please select another.';
        }

        return JSON.stringify(result);
	},
    type: 'VenueUtils'
});
